import json
import os
from pathlib import Path
from urllib import parse, request

tracking_uri = os.environ['MLFLOW_TRACKING_URI'].rstrip('/')
flow_run_id = os.environ.get('ORCH_FLOW_RUN_ID', '').strip()
job_name = os.environ.get('ORCH_JOB_NAME', '').strip()
artifact_dir = Path(os.environ['ORCH_ENGINE_ARTIFACT_DIR'])
manifest_path = Path(os.environ['ORCH_ENGINE_ARTIFACT_MANIFEST_PATH'])
headers = {
    'Content-Type': 'application/json',
    'User-Agent': 'orchestrator-standard-dummy/1.0',
}


def post(path: str, payload: dict[str, object]) -> dict[str, object]:
    req = request.Request(
        f'{tracking_uri}{path}',
        data=json.dumps(payload, ensure_ascii=True).encode('utf-8'),
        headers=headers,
        method='POST',
    )
    with request.urlopen(req, timeout=30) as resp:  # nosec B310
        raw = resp.read().decode('utf-8')
    return json.loads(raw or '{}')


def get(path: str, query: dict[str, str]) -> dict[str, object]:
    qs = parse.urlencode(query)
    req = request.Request(
        f'{tracking_uri}{path}?{qs}',
        headers={'User-Agent': headers['User-Agent']},
        method='GET',
    )
    with request.urlopen(req, timeout=30) as resp:  # nosec B310
        raw = resp.read().decode('utf-8')
    return json.loads(raw or '{}')


created = post(
    '/api/2.0/mlflow/runs/create',
    {
        'experiment_id': '0',
        'start_time': 0,
        'tags': [
            {'key': 'e2e_flow_run_id', 'value': flow_run_id},
            {'key': 'e2e_dummy', 'value': 'standard'},
            {'key': 'job_name', 'value': job_name},
        ],
    },
)
run = created.get('run', {})
info = run.get('info', {}) if isinstance(run, dict) else {}
run_id = str(info.get('run_id', '')).strip()
if not run_id:
    raise SystemExit('mlflow run_id missing')

post(
    '/api/2.0/mlflow/runs/set-tag',
    {'run_id': run_id, 'key': 'dummy_status', 'value': 'ok'},
)
retrieved = get('/api/2.0/mlflow/runs/get', {'run_id': run_id})
retrieved_run = retrieved.get('run', {}) if isinstance(retrieved, dict) else {}
retrieved_info = retrieved_run.get('info', {}) if isinstance(retrieved_run, dict) else {}
if str(retrieved_info.get('run_id', '')).strip() != run_id:
    raise SystemExit('mlflow run fetch mismatch')

artifact_dir.mkdir(parents=True, exist_ok=True)
scene_dir = artifact_dir / 'scene'
scene_dir.mkdir(parents=True, exist_ok=True)

scene_path = scene_dir / 'scene.json'
scene_path.write_text(
    json.dumps(
        {
            'scene_id': 'local-e2e-scene',
            'version_id': 'attempt-1',
        },
        ensure_ascii=True,
        indent=2,
    ),
    encoding='utf-8',
)

verify_path = scene_dir / 'verification.json'
verify_path.write_text(
    json.dumps({'status': 'ok'}, ensure_ascii=True, indent=2), encoding='utf-8'
)

manifest_path.write_text(
    json.dumps(
        {
            'schema_version': 1,
            'artifacts': [
                {
                    'logical_name': 'scene_json',
                    'relative_path': 'scene/scene.json',
                    'content_type': 'application/json',
                    'mlflow_tag': 'artifact_scene_uri',
                },
                {
                    'logical_name': 'verification_json',
                    'relative_path': 'scene/verification.json',
                    'content_type': 'application/json',
                    'mlflow_tag': 'artifact_verification_uri',
                }
            ],
        },
        ensure_ascii=True,
        indent=2,
    ),
    encoding='utf-8',
)
print(
    json.dumps(
        {
            'ok': True,
            'message': 'fixed-standard-dummy-ok',
            'mlflow_run_id': run_id,
            'flow_run_id': flow_run_id,
            'scene_id': 'local-e2e-scene',
            'version_id': 'attempt-1',
        },
        ensure_ascii=True,
    )
)
